using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using DesktopCritters.Core;
namespace DesktopCritters;
public static class TeamTests {
 public static void Run(string directory,Action<bool,string> check){
  var folder=Path.Combine(directory,"team-tests-"+Guid.NewGuid());var library=new CharacterLibrary(folder);CharacterLibrary.Shared=library;var w=new World(1440,900,12);var before=w.SaveJson();
  check(library.Left=="roach"&&library.Selected=="ant","fresh install defaults to original pair");check(library.All.Count()==11&&library.All.All(s=>library.Image(s.Id)!=null),"both teams share eleven decodable presets");
  library.Select("rat",Species.Roach);library.Select("nailong",Species.Ant);library.Apply(w);check(library.Left=="rat"&&library.Selected=="nailong","left and right selections are independent");check(w.SaveJson()==before,"switching both teams preserves complete ecology");var loaded=new CharacterLibrary(folder);check(loaded.Left=="rat"&&loaded.Selected=="nailong","both selections survive restart");
  library.Select("nailong",Species.Roach);library.Apply(w);check(library.Left==library.Selected&&w.TeamName(Species.Roach)!=w.TeamName(Species.Ant),"same character still belongs to distinct teams");var left=new Bug{Id=880,Species=Species.Roach,P=new V(400,400),Angle=Math.PI/2};check(w.BodyHit(left,new V(400,384))&&!w.BodyHit(left,new V(442,400)),"left upright avatar hit target matches image");check(w.SafeBug(new V(-20,-20),left).X>=43,"left avatar stays within desktop");check(!w.BeginFlight(left),"non-roach left pet cannot inherit wings");
  library.Select("roach",Species.Ant);library.Apply(w);var right=new Bug{Id=881,Species=Species.Ant,P=new V(500,400)};check(w.BeginFlight(right),"right-team roach can take off");w.Bugs.Clear();w.Bugs.Add(right);library.Select("rat",Species.Ant);library.Apply(w);check(right.Flight==null,"changing flying pet safely lands it");check(w.BodyHit(right,new V(525,400)),"right rat uses full body hit target");
  string Source(string name){var path=Path.Combine(folder,name+".png");Directory.CreateDirectory(folder);using(var stream=Application.GetResourceStream(new Uri("pack://application:,,,/Characters/"+name+".png"))!.Stream)using(var output=File.Create(path))stream.CopyTo(output);return path;}
  var first=library.Import(Source("nailong"),Species.Roach);var second=library.Import(Source("niulai"),Species.Ant);check(first.Id!=second.Id&&library.Left==first.Id&&library.Selected==second.Id,"two independent uploaded pets can coexist");loaded=new CharacterLibrary(folder);check(loaded.Left==first.Id&&loaded.Selected==second.Id&&loaded.Image(first.Id)!=null&&loaded.Image(second.Id)!=null,"both uploaded images reopen");
  try{library.Select("missing",Species.Roach);check(false,"missing left asset rejected");}catch(InvalidDataException){check(library.Left==first.Id&&library.Selected==second.Id,"invalid left selection preserves both teams");}
  library.Apply(w);w.Bugs.Clear();w.Bugs.Add(left);right.P=new V(450,400);w.Bugs.Add(right);w.Eggs.Clear();w.Corpses.Clear();w.Splats.Clear();w.Interactive=true;var egg=w.EmittedEgg(left,990);check(egg.LayStart!.Value.X==left.P.X&&egg.LayStart.Value.Y>left.P.Y,"upright pet lays egg from visible lower body");w.Eggs.Add(egg);w.MarkShelter(egg.P);egg.LayAge=3;check(w.EggOccluded(egg),"custom team eggs hide in folder regions");w.Spray(new V(425,400));check(w.Bugs.Count==0&&w.Corpses.Count==2&&w.Eggs.Count==1,"spray kills both uploaded teams and leaves egg");check(w.Splats.Count==0,"custom pets do not leak roach juice");w.SweepAt(new V(425,400));check(w.Corpses.Count==0,"broom cleans both custom corpses");
  w.RoachBirth=10000;w.AntBirth=10000;w.Eggs.Clear();w.Eggs.Add(new Egg{Id=991,Species=Species.Roach,P=new V(500,500),HatchTime=1,Generation=2});w.Life(2);check(w.Bugs.Any(b=>b.Species==Species.Roach&&!b.Adult)&&w.LeftPetId==first.Id,"newborns inherit custom left team");check(w.ReportText().Contains("左队")&&w.ReportText().Contains("右队"),"report distinguishes customized teams");
  library.RestorePair();library.Apply(w);check(library.Left=="roach"&&library.Selected=="ant"&&library.Customs.Count==2,"default pair restore retains custom library");var file=Path.Combine(folder,"appearance-v1.json");var old="{\"version\":1,\"selected\":\"niulai\",\"customs\":[]}";File.WriteAllText(file,old);loaded=new CharacterLibrary(folder);check(loaded.Left=="roach"&&loaded.Selected=="niulai","legacy one-side settings migrate to right team");check(File.ReadAllText(file)==old,"migration preserves original file until user chooses");File.WriteAllText(file,"{\"version\":1,\"selected\":\"niulai\",\"left\":\"missing\",\"customs\":[]}");loaded=new CharacterLibrary(folder);check(loaded.Left=="roach"&&loaded.Selected=="niulai","missing left asset leaves valid right choice intact");
 }
 public static void Render(string directory){var library=new CharacterLibrary(Path.Combine(directory,"team-render"),false);CharacterLibrary.Shared=library;
  foreach(var item in new[]{("nailong","rat","windows-two-teams"),("usagi","usagi","windows-same-pets"),("capybara","roach","windows-right-roach-flight")}){library.Select(item.Item1,Species.Roach);library.Select(item.Item2,Species.Ant);var w=new World(1200,800,42);w.Bugs.Clear();w.Eggs.Clear();w.Foods.Clear();library.Apply(w);for(int i=0;i<2;i++)for(int n=0;n<5;n++)w.Bugs.Add(new Bug{Id=i*10+n,Species=(Species)i,P=new V(210+i*540+n%2*115,275+n/2*140),Angle=i==0?0:Math.PI,Phase=1.6,Growth=n==4?.3:1,Bulk=n==0?.7:.12,ShownBulk=n==0?.7:.12});if(item.Item2=="roach"){var b=w.Bugs[5];w.BeginFlight(b);b.Flight!.Elapsed=1;w.Fly(b,0);}w.AddFood(new V(600,470),Snack.Pizza);var visual=new DrawingVisual();using(var c=visual.RenderOpen()){c.DrawRectangle(Art.Cream,null,new Rect(0,0,1200,800));Art.Text(c,w.TeamName(Species.Roach),80,50,28);Art.Text(c,w.TeamName(Species.Ant),675,50,28);Art.Draw(w,c,false);}var bitmap=new RenderTargetBitmap(1200,800,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(Path.Combine(directory,item.Item3+".png"));png.Save(output);}
 }
}
